import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import openapiTS, { astToString } from 'openapi-typescript';
import { format, resolveConfig } from 'prettier';
import { z } from 'zod';

/** The package root (`packages/api-client`). */
export const PACKAGE_ROOT = fileURLToPath(new URL('../..', import.meta.url));
/** The committed OpenAPI spec the client is generated from (CONTEXT_PACK §9, API-003). */
const SPEC_FILE = new URL('../../../../docs/api/openapi.json', import.meta.url);
/** The committed generated files, relative to the package root. */
export const GENERATED_DIR = 'src/generated';

/** Reads the committed spec as data. */
export function readSpec(): unknown {
  return JSON.parse(readFileSync(SPEC_FILE, 'utf8'));
}

const HTTP_METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'] as const;

const parameterSchema = z.object({
  name: z.string().min(1),
  in: z.enum(['path', 'query', 'header', 'cookie']),
  required: z.boolean().optional(),
});

/** A parameter written as a reference. The generator does not resolve references, so it refuses them. */
const referenceSchema = z.object({ $ref: z.string() });

const operationSchema = z.object({
  operationId: z.string().min(1),
  parameters: z.array(z.union([parameterSchema, referenceSchema])).optional(),
});

/** The parts of the OpenAPI document this generator reads. Everything else is left to openapi-typescript. */
const specSchema = z.object({
  servers: z.array(z.object({ url: z.string() })).min(1),
  paths: z.record(z.string(), z.record(z.string(), z.unknown())),
});

export interface GeneratedFiles {
  /** `src/generated/schema.ts`: the types of every path, operation and component schema. */
  readonly schema: string;
  /** `src/generated/operations.ts`: the method, path and parameter locations per `operationId`. */
  readonly operations: string;
}

interface OperationMeta {
  readonly operationId: string;
  readonly method: string;
  readonly path: string;
  readonly pathParams: readonly string[];
  readonly queryParams: readonly string[];
  readonly requiredHeaders: readonly string[];
}

/** Reads every operation of the spec, sorted by `operationId` so the output is stable. */
export function operationsOf(spec: unknown): readonly OperationMeta[] {
  const { servers, paths } = specSchema.parse(spec);
  const serverUrl = servers[0]?.url ?? '';
  // Clients join the origin they are given with the spec's server path (`/v1`), so the paths are
  // emitted in full. A server URL must be a path, never an absolute URL that could redirect traffic.
  if (!/^\/[^?#]*$/.test(serverUrl))
    throw new Error(`server url must be a path, found ${serverUrl}`);
  const basePath = serverUrl.replace(/\/$/, '');
  const found: OperationMeta[] = [];
  for (const route of Object.keys(paths).sort()) {
    for (const method of HTTP_METHODS) {
      const raw = paths[route]?.[method];
      if (raw === undefined) continue;
      const operation = operationSchema.parse(raw);
      const parameters: z.infer<typeof parameterSchema>[] = [];
      for (const parameter of operation.parameters ?? []) {
        if (!('name' in parameter)) {
          throw new Error(
            `${operation.operationId}: $ref parameters are not supported by the generator`,
          );
        }
        parameters.push(parameter);
      }
      found.push({
        operationId: operation.operationId,
        method: method.toUpperCase(),
        path: `${basePath}${route}`,
        pathParams: parameters.filter((p) => p.in === 'path').map((p) => p.name),
        queryParams: parameters.filter((p) => p.in === 'query').map((p) => p.name),
        requiredHeaders: parameters
          .filter((p) => p.in === 'header' && p.required === true)
          .map((p) => p.name),
      });
    }
  }
  found.sort((a, b) => a.operationId.localeCompare(b.operationId));
  const ids = found.map((operation) => operation.operationId);
  const duplicate = ids.find((id, index) => ids.indexOf(id) !== index);
  if (duplicate !== undefined) throw new Error(`duplicate operationId ${duplicate}`);
  return found;
}

const HEADER =
  '// Generated by `pnpm --filter @blackwing/api-client api-client:gen` from docs/api/openapi.json.\n// Do not edit by hand: `pnpm test` fails when this file is stale.\n';

function renderOperations(operations: readonly OperationMeta[]): string {
  const entries = operations.map(
    (operation) =>
      `  ${JSON.stringify(operation.operationId)}: { method: ${JSON.stringify(operation.method)}, path: ${JSON.stringify(operation.path)}, pathParams: ${JSON.stringify(operation.pathParams)}, queryParams: ${JSON.stringify(operation.queryParams)}, requiredHeaders: ${JSON.stringify(operation.requiredHeaders)} },`,
  );
  return `${HEADER}\nexport const OPERATIONS = {\n${entries.join('\n')}\n} as const;\n\nexport type OperationId = keyof typeof OPERATIONS;\n`;
}

async function formatTs(source: string, file: string): Promise<string> {
  const config = await resolveConfig(file);
  return format(source, { ...config, filepath: file });
}

/**
 * Renders the client's generated files from an OpenAPI 3.1 document. The output depends only on the
 * spec, so rendering twice gives the same bytes (the drift test relies on this).
 */
export async function renderGeneratedFiles(spec: unknown): Promise<GeneratedFiles> {
  const schemaFile = `${PACKAGE_ROOT}/${GENERATED_DIR}/schema.ts`;
  const operationsFile = `${PACKAGE_ROOT}/${GENERATED_DIR}/operations.ts`;
  const ast = await openapiTS(spec as Parameters<typeof openapiTS>[0]);
  const schema = await formatTs(`${HEADER}\n${astToString(ast)}`, schemaFile);
  const operations = await formatTs(renderOperations(operationsOf(spec)), operationsFile);
  return { schema, operations };
}
